"""Golden-output regression tests for TiRexForecaster."""

import numpy as np
import pytest

from sktime.datasets import load_airline
from sktime.forecasting.tirex import TiRexForecaster
from sktime.tests.test_switch import run_test_for_class

pytestmark = pytest.mark.skipif(
    not run_test_for_class(TiRexForecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)

# Reference forecasts were generated by calling upstream TiRex directly,
# bypassing sktime: tirex.load_model(model, device="cpu", backend="torch") and
# model.forecast(context, prediction_length=max(fh)), taking the mean output
# (the 0.5 quantile) at the steps in fh. Context is the first 132 values of
# load_airline as a float32 tensor of shape [1, 132], on CPU.
# Environment: python 3.12.13, tirex-ts 1.4.2, torch 2.15.0, numpy 2.5.5.
# Checkpoints at Hugging Face revisions (TiRexForecaster does not take a revision):
#   NX-AI/TiRex               43ebaaff068c1390785c387b3e5178df3f4c92ca
#   NX-AI/TiRex-1.1-gifteval  01b1ebc83a87e82b119f907fe7e43d015db23e9d
# The generator script is in the description of sktime PR #11543.
# Cases store the first and last three forecast values.
_TIREX_REFERENCE_CASES = [
    pytest.param(
        "NX-AI/TiRex",
        list(range(1, 13)),
        [415.618652, 393.354736, 451.315674],
        [454.431152, 388.240601, 423.835266],
        id="tirex-fh12",
    ),
    # fh beyond the output patch size of 32 takes a second rollout step
    pytest.param(
        "NX-AI/TiRex",
        list(range(1, 49)),
        [415.618652, 393.354736, 451.315674],
        [499.955109, 439.484497, 460.58255],
        id="tirex-fh48",
    ),
    # non-contiguous fh, checks the steps are selected by fh
    pytest.param(
        "NX-AI/TiRex",
        [2, 5, 12],
        [393.354736, 459.289825, 423.835266],
        [393.354736, 459.289825, 423.835266],
        id="tirex-fh-gaps",
    ),
    pytest.param(
        "NX-AI/TiRex-1.1-gifteval",
        list(range(1, 13)),
        [410.187042, 391.728149, 447.924591],
        [450.233704, 398.519684, 436.355408],
        id="tirex-1.1-gifteval-fh12",
    ),
]


@pytest.mark.parametrize("model,fh,expected_head,expected_tail", _TIREX_REFERENCE_CASES)
def test_tirex_airline_predictions_match_upstream(
    model, fh, expected_head, expected_tail
):
    """TiRexForecaster predictions match the upstream TiRex outputs."""
    y = load_airline()
    y_train = y.iloc[:-12]
    forecaster = TiRexForecaster(model=model, device="cpu", license_accepted=True)

    y_pred = forecaster.fit(y_train).predict(fh=fh).to_numpy()

    assert len(y_pred) == len(fh)
    np.testing.assert_allclose(y_pred[:3], expected_head, rtol=1e-5, atol=1e-4)
    np.testing.assert_allclose(y_pred[-3:], expected_tail, rtol=1e-5, atol=1e-4)
